fn solve(n: i8, s: Vec<char>) -> i8 {
    // Precondition: n must be non-negative and the length of s must be equal to n
    // Ensures: The function returns the number of transitions between regions A and B
    // Requires: n >= 0 && s.len() == n
    // Ensures: result >= 0
    // Decreases: n
    // Invariant: x >= 0 && y >= 0 && transitions >= 0
    // Invariant: last_region is either None or Some("A") or Some("B")
    // Invariant: current_region is either None or Some("A") or Some("B")
    // Invariant: move_char is either 'U' or 'R'
    // Invariant: for each move_char in s, move_char is 'U' or 'R'
    // Invariant: last_region is updated correctly based on the current_region

    assert!(n >= 0);
    assert!(s.len() == n as usize);

    if n == 0 {
        return 0;
    }

    let mut x = 0;
    let mut y = 0;
    let mut transitions = 0;
    let mut last_region = None; // None means we are on the border

    for &move_char in &s {
        // Ensure that move_char is either 'U' or 'R'
        assert!(move_char == 'U' || move_char == 'R');

        match move_char {
            'U' => y += 1,
            'R' => x += 1,
            _ => unreachable!(), // Since input is guaranteed to be 'U' or 'R'
        }

        // Determine the current region
        let current_region = if x > y {
            Some("A") // Region A
        } else if y > x {
            Some("B") // Region B
        } else {
            None // On the border
        };

        // Check for transitions
        if let Some(region) = current_region {
            if last_region.is_none() {
                // We just left the border, do not count this as a transition
                last_region = Some(region);
            } else if last_region != Some(region) {
                // We have transitioned between regions
                transitions += 1;
                last_region = Some(region);
            }
        } else {
            // We are on the border, reset last_region
            last_region = None;
        }
    }

    transitions
}